def changed_paths(before, after):
    """Return sorted dot-separated paths for additions, removals, or unequal leaves.

    Recurses only where both values are dicts; treats all other values atomically.
    """
    paths = set()
    _compare(before, after, (), paths)
    return sorted(paths)


def _compare(before, after, path_parts, paths):
    all_keys = set(before) | set(after)
    for key in all_keys:
        path_parts_new = path_parts + (key,)
        path = ".".join(path_parts_new)

        if key not in before:
            paths.add(path)
        elif key not in after:
            paths.add(path)
        else:
            b_val = before[key]
            a_val = after[key]
            if isinstance(b_val, dict) and isinstance(a_val, dict):
                _compare(b_val, a_val, path_parts_new, paths)
            elif b_val != a_val:
                paths.add(path)
