def coalesce(intervals):
    """Merge overlapping or touching half-open integer intervals (start, end).

    - Empty intervals (start == end) are discarded.
    - Raises ValueError if start > end.
    - Returns a sorted list of merged tuples without mutating the input.
    """
    valid = []
    for start, end in intervals:
        if start > end:
            raise ValueError(f"Invalid interval: start ({start}) > end ({end})")
        if start == end:
            continue
        valid.append((start, end))

    valid.sort(key=lambda x: (x[0], x[1]))

    if not valid:
        return []

    result = [valid[0]]
    for start, end in valid[1:]:
        prev_start, prev_end = result[-1]
        if start <= prev_end:
            result[-1] = (prev_start, max(prev_end, end))
        else:
            result.append((start, end))

    return result
```

