def delays(attempts, base, cap):
    if attempts < 1 or base < 0 or cap < 0:
        raise ValueError("attempts must be >= 1, base must be >= 0, cap must be >= 0")
    return [min(base * 2**i, cap) for i in range(attempts - 1)]
