def unique_latest(records):
    best = {}
    order = []
    for record in records:
        rid = record["id"]
        if rid not in best:
            best[rid] = record
            order.append(rid)
        else:
            if record["timestamp"] >= best[rid]["timestamp"]:
                best[rid] = record
    return [best[rid] for rid in order]
