from bisect import bisect_right


def histogram(edges, values):
    """
    Count values in bins defined by edges.

    Bins are half-open [edge_i, edge_{i+1}); the final bin is closed
    [edge_{n-2}, edge_{n-1}]. Out-of-range values are ignored.
    """
    # Validate edges
    if not isinstance(edges, (list, tuple)):
        raise ValueError("edges must be a list")
    if len(edges) < 2:
        raise ValueError("edges must have at least two elements")
    for e in edges:
        if isinstance(e, bool) or not isinstance(e, (int, float)):
            raise ValueError("edges must contain only numbers")
        if e != e:  # NaN check
            raise ValueError("edges must not contain NaN")
    for i in range(len(edges) - 1):
        if edges[i] >= edges[i + 1]:
            raise ValueError("edges must be strictly increasing")

    counts = [0] * (len(edges) - 1)

    for v in values:
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            continue
        if v != v:  # NaN
            continue
        if v < edges[0] or v > edges[-1]:
            continue
        if v == edges[-1]:
            idx = len(edges) - 2
        else:
            idx = bisect_right(edges, v) - 1
        counts[idx] += 1

    return counts
```

