def flatten(value):
    if not value:
        return {}

    result = {}
    for key, val in value.items():
        if isinstance(val, dict):
            if not val:
                result[key] = {}
            else:
                sub = flatten(val)
                for sub_key, sub_val in sub.items():
                    result[f"{key}.{sub_key}"] = sub_val
        else:
            result[key] = val

    return result
