def normalize(path: str) -> str:
    """Normalize an absolute POSIX-like path.

    Raises ValueError if the path is not absolute.
    Collapses repeated slashes, removes '.' components,
    resolves '..' without going above the root, and
    never returns a trailing slash (except for root '/').
    """
    if not path.startswith('/'):
        raise ValueError(f"path must be absolute: {path!r}")

    parts = path.split('/')
    stack: list[str] = []

    for part in parts:
        if part == '' or part == '.':
            continue
        elif part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)

    if not stack:
        return '/'
    return '/' + '/'.join(stack)
```

